def icon(name: str, size: int = 16, color: str = "currentColor",
         cls: str = "", style: str = "") -> str:
    """Return an inline <svg> for a Lucide icon name (with or without 'lucide:')."""
    key = name.split(":")[-1]
    body = ICONS.get(key)
    if body is None:
        body = ICONS["wrench"]
    c = f' class="{cls}"' if cls else ""
    s = f";{style}" if style else ""
    return (f'<svg{c} width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
            f'stroke="{color}" stroke-width="2" stroke-linecap="round" '
            f'stroke-linejoin="round" style="display:inline-block;vertical-align:-.125em;'
            f'flex-shrink:0{s}">{body}</svg>')
